import type { TriageTicketInput, TriageTicketOutput, TriageTicketCaps } from "./contract.js";
import { loadAccount } from "./load-account/impl.js";
import { classifyTicket } from "./classify-ticket/impl.js";
import { scorePriority } from "./score-priority/impl.js";
import { draftAlert } from "./draft-alert/impl.js";

/** Work out how urgent one ticket is for the customer who raised it, and draft the alert to go out about it. */
export async function triageTicket(input: TriageTicketInput, caps: TriageTicketCaps): Promise<TriageTicketOutput> {
  const { accountId, ticket } = input;

  const { account } = await loadAccount({ accountId }, caps);

  const { category, urgent } = await classifyTicket({ ticket }, caps);

  const { priority, reason } = await scorePriority({ account, category, urgent }, caps);

  const { alert } = await draftAlert({ priority, reason, account, ticket }, caps);

  return { priority, alert };
}
